#!/usr/bin/env bash
# Correctifs du stockage : gardes d'écriture (renommer, déplacer, libellé) et de lecture (métadonnées,
# recherche), remplacer = publier (mayReplace), doublons d'un même envoi, erreurs lisibles, racine alignée
# sur le serveur, mémoire bornée, séquence d'envoi unique. Prérequis : apply-docs-domaine.sh. Aucune migration.
# Usage (racine du repo) : bash apply-fix-stockage.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"packages/backend/src/trpc/middleware.ts" 2>/dev/null | grep -qF "sameAppRoot"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "Le nom affiché n’est pas une identité" "apps/web/content/docs/dev/domaine/un-modele-qui-s-ouvre.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-domaine.sh"; exit 1; }
MODIFIED=("apps/web/src/app/(public)/mes-espaces/[groupId]/page.tsx" "apps/web/src/app/(public)/mes-espaces/page.tsx" "apps/web/src/app/api/media/public/r2/[...path]/route.ts" "apps/web/src/app/api/media/r2/[...path]/route.ts" "apps/web/src/features/admin/library/forms/DragNDropForm.tsx" "apps/web/src/features/admin/perso/PersoPhotoUploader.tsx" "apps/web/src/features/common-repository/CommonRepositoryUpload.tsx" "packages/backend/src/modules/media/router.ts" "packages/backend/src/modules/media/services/assertStatusChangeDoesntUnpublishReferencedAssets.service.ts" "packages/backend/src/modules/media/services/mediaDerivatives.service.ts" "packages/backend/src/modules/media/services/resolveGroupBaseFolder.service.ts" "packages/backend/src/modules/media/services/resolvePersoBaseFolder.service.ts" "packages/backend/src/modules/memberGroups/assertCanTrashPaths.service.ts" "packages/backend/src/modules/storage/adapters/r2/client.ts" "packages/backend/src/modules/storage/adapters/r2/r2StorageAdapter.ts" "packages/backend/src/modules/storage/assertUploadDestinationAllowed.service.ts" "packages/backend/src/modules/storage/router.ts" "packages/backend/src/modules/storage/services/resolvePendingUploadFolder.service.ts" "packages/backend/src/modules/storage/virtualStorage.ts" "packages/backend/src/modules/trash/router.ts" "packages/backend/src/trpc/middleware.ts" "packages/contracts/src/storage/r2-upload.schema.ts")
EXPECT=("cbc14e73000e:apps/web/src/app/(public)/mes-espaces/[groupId]/page.tsx" "425274d98ad8:apps/web/src/app/(public)/mes-espaces/page.tsx" "aeadd7e2865f:apps/web/src/app/api/media/public/r2/[...path]/route.ts" "2eb187c0b846:apps/web/src/app/api/media/r2/[...path]/route.ts" "730df8eea4f7:apps/web/src/features/admin/library/forms/DragNDropForm.tsx" "054c0b6b5bc3:apps/web/src/features/admin/perso/PersoPhotoUploader.tsx" "7171de1a928f:apps/web/src/features/common-repository/CommonRepositoryUpload.tsx" "c98b1c0ebbe8:packages/backend/src/modules/media/router.ts" "967620c7d2dd:packages/backend/src/modules/media/services/assertStatusChangeDoesntUnpublishReferencedAssets.service.ts" "af338d6d556b:packages/backend/src/modules/media/services/mediaDerivatives.service.ts" "1d1e74368781:packages/backend/src/modules/media/services/resolveGroupBaseFolder.service.ts" "205f21bd08d5:packages/backend/src/modules/media/services/resolvePersoBaseFolder.service.ts" "e28a3a3b596e:packages/backend/src/modules/memberGroups/assertCanTrashPaths.service.ts" "e18c2bfafc0e:packages/backend/src/modules/storage/adapters/r2/client.ts" "01eaa49df150:packages/backend/src/modules/storage/adapters/r2/r2StorageAdapter.ts" "0471c10f83cf:packages/backend/src/modules/storage/assertUploadDestinationAllowed.service.ts" "397eb53489af:packages/backend/src/modules/storage/router.ts" "470ba75f9802:packages/backend/src/modules/storage/services/resolvePendingUploadFolder.service.ts" "4f4ba1de036f:packages/backend/src/modules/storage/virtualStorage.ts" "13aa2ac47872:packages/backend/src/modules/trash/router.ts" "9cf4e2ffb535:packages/backend/src/trpc/middleware.ts" "10e39587ebfe:packages/contracts/src/storage/r2-upload.schema.ts")
DIFF=0; for e in "${EXPECT[@]}"; do h=${e%%:*}; f=${e#*:}; c=$(git rev-parse "HEAD:$f" 2>/dev/null | cut -c1-12); if [ "$c" != "$h" ]; then [ $DIFF = 0 ] && echo "❌ ces fichiers ne sont pas dans l'état attendu (rien n'a été touché) :"; echo "   $f"; DIFF=1; fi; done; [ $DIFF = 0 ] || exit 1
CREATED=("apps/web/src/features/media/uploadToR2.ts" "packages/backend/src/modules/memberGroups/assertCanReadPaths.service.ts" "packages/backend/src/modules/memberGroups/assertCanWritePaths.service.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "sameAppRoot" "packages/backend/src/trpc/middleware.ts" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

